	int err;

	idr_init(&file_priv->context_idr);
	mutex_init(&file_priv->context_idr_lock);

	mutex_lock(&i915->drm.struct_mutex);
	ctx = i915_gem_create_context(i915);
	mutex_unlock(&i915->drm.struct_mutex);
